#!/usr/bin/env bash
# recipes/crate-intrusive-collections--0-9-6/build.sh -- stage the intrusive-collections 0.9.6 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/intrusive-collections-0.9.6"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"b694dc9f70c3bda874626d2aed13b780f137aab435f4e9814121955cf706122e"}\n' > "${dest}/.cargo-checksum.json"
